// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _test(uint256 initialMin, uint256 newMin) internal {
        vm.assume(initialMin != newMin);
        try c.SetMinSum(initialMin) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 before;
        try c.MinSum() returns (uint256 __r) { before = __r; } catch { return; }
        try c.SetMinSum(newMin) {} catch { return; }
        uint256 afterSet;
        try c.MinSum() returns (uint256 __r) { afterSet = __r; } catch { return; }
        assertTrue(afterSet == before);
    }

    function testFuzz_test(uint256 initialMin, uint256 newMin) public {
        _test(initialMin, newMin);
    }

    receive() external payable {}
}
